export const QUIZ_ITEMS = [
  { id: "2365", section: "الفرائض والمواريث", category: "المواريث", level: "متوسط", question: "ما موانع الإرث الثلاثة في الفقه الإسلامي؟", answer: "ثلاثة: 1- القتل العمد العدوان (القاتل لا يرث ممن قتله). 2- اختلاف الدين (المسلم لا يرث الكافر ولا الكافر المسلم بالإجماع). 3- الرق (العبد لا يرث ولا يُورَث في حكمه).", explanation: "يُستفاد منه في باب المواريث. يُستفاد منه في باب المواريث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2366", section: "الفرائض والمواريث", category: "الفروض", level: "صعب", question: "كم فريضة حددها القرآن الكريم في المواريث؟", answer: "ستة فروض مقدّرة: النصف (1/2)، الربع (1/4)، الثمن (1/8)، الثلثان (2/3)، الثلث (1/3)، السدس (1/6) — وكل منها لمستحق محدد بآيات النساء (11-12 و176).", explanation: "يُستفاد منه في باب الفروض. يُستفاد منه في باب الفروض مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2367", section: "الفرائض والمواريث", category: "الحجب", level: "صعب", question: "ما الفرق بين حجب الحرمان وحجب النقصان؟", answer: "حجب الحرمان: حجب الوارث كلياً عن الإرث — كحجب الأخ بالابن. حجب النقصان: نقل الوارث من فرض أعلى إلى أدنى — كانتقال الزوج من النصف (1/2) إلى الربع (1/4) عند وجود الولد.", explanation: "يُستفاد منه في باب الحجب. يُستفاد منه في باب الحجب مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2368", section: "الفرائض والمواريث", category: "أصحاب الفروض", level: "متوسط", question: "من الورثة الذين لا يُحجبون حجب حرمان أبداً؟", answer: "ستة: الأب، الأم، الابن، البنت، الزوج، الزوجة — لا يُحجبون حجب حرمان مطلقاً وإن نقص نصيبهم بحجب النقصان (كانتقال الزوج من النصف إلى الربع عند وجود الولد). أما ابن الابن (الحفيد) فليس منهم؛ إذ يُحجب حجب حرمان تاماً بوجود الابن.", explanation: "يُستفاد منه في باب أصحاب الفروض. يُستفاد منه في باب أصحاب الفروض مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2369", section: "الفرائض والمواريث", category: "الوصية", level: "متوسط", question: "ما أقصى ما يجوز للمسلم إيصاء به من ماله؟", answer: "لا تجوز الوصية بأكثر من ثلث المال للأجانب — لحديث سعد رضي الله عنه: «الثلث والثلث كثير» (البخاري). ولا تجوز الوصية لوارث ألبتة إلا بإجازة بقية الورثة.", explanation: "يُستفاد منه في باب الوصية. يُستفاد منه في باب الوصية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2370", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من هم أصحاب الفروض المحددة في القرآن؟", answer: "أصحاب الفروض المقدَّرة في القرآن: 1) الزوج: النصف أو الربع. 2) الزوجة/الزوجات: الربع أو الثمن. 3) الأم: الثلث أو السدس. 4) الأب: السدس (عصبة). 5) البنت/البنات: النصف أو الثلثان. 6) الأخت الشقيقة: النصف أو الثلثان. 7) الجدة: السدس. 8) الأخ لأم والأخت لأم: السدس أو الثلث.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2371", section: "الفرائض والمواريث", category: "الميراث", level: "متوسط", question: "من الذين يُحجَبون حجب حرمان من الميراث؟ اذكر أمثلة.", answer: "حجب الحرمان: حرمان الوارث من الإرث بسبب وجود وارث أقوى منه. أمثلة: 1) الجد يُحجَب بوجود الأب. 2) الإخوة يُحجَبون بوجود الابن أو الأب. 3) بنت الابن تُحجَب بوجود بنتين فأكثر إلا إذا وُجد معها ابن ابن. 4) الأخت لأم تُحجَب بوجود الفرع الوارث أو الأصل الذكر. والمانعون من الإرث: الكفر، والقتل العمد، والرق.", explanation: "يُستفاد منه في باب الميراث. يُستفاد منه في باب الميراث مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2372", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "من قائد موقعة القادسية التي فتح بها العراق؟", answer: "سعد بن أبي وقاص رضي الله عنه — قائد موقعة القادسية التي فتح بها العراق للإسلام.", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2373", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "من الصحابي الذي فتح مصر للإسلام؟", answer: "عمرو بن العاص رضي الله عنه — الصحابي الذي فتح مصر للإسلام في عهد عمر بن الخطاب.", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2374", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "من القائد الذي فتح الأندلس؟", answer: "طارق بن زياد؛ بدأ الفتح سنة 92هـ بأمر موسى بن نصير والي إفريقية، ثم عبر إليه موسى بن نصير في العام التالي فأتمّا الفتح معًا", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2375", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "في أي سنة فتح طارق بن زياد الأندلس؟", answer: "92هـ / 711م — سنة فتح طارق بن زياد الأندلس عبر مضيق جبل طارق.", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2376", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "من مؤسس الدولة الأموية؟", answer: "معاوية بن أبي سفيان — مؤسس الدولة الأموية، وكان والياً على الشام قبل الخلافة.", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2377", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "ما عاصمة الدولة الأموية؟", answer: "دمشق — عاصمة الدولة الأموية التي أسسها معاوية بن أبي سفيان.  — يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2378", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "من مؤسس الدولة العباسية؟", answer: "أبو العباس السفاح — مؤسس الدولة العباسية، أول خلفائها (ت 136هـ).", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2379", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "من الخليفة العباسي الذي بنى مدينة بغداد؟", answer: "أبو جعفر المنصور — الخليفة العباسي الذي بنى مدينة بغداد واتخذها عاصمة (762م).", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2380", section: "التاريخ الإسلامي", category: "المعارك", level: "متوسط", question: "ما اسم المعركة التي أوقف فيها المسلمون الزحف المغولي؟", answer: "معركة عين جالوت — المعركة التي أوقف فيها المسلمون الزحف المغولي سنة 658هـ.", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2381", section: "التاريخ الإسلامي", category: "المعارك", level: "متوسط", question: "من قاد المسلمين في معركة عين جالوت؟", answer: "السلطان قطز — قائد المسلمين في معركة عين جالوت إلى جانب الظاهر بيبرس.", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2382", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "من الذي فتح القسطنطينية؟", answer: "السلطان محمد الفاتح — الذي فتح القسطنطينية ووُعد بفتحها في الحديث الصحيح.", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2383", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "في أي سنة فتحت القسطنطينية؟", answer: "857هـ / 1453م — سنة فتح القسطنطينية على يد السلطان محمد الفاتح.", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2384", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "ما الخليفة الأموي الذي بنى قبة الصخرة في القدس؟", answer: "عبد الملك بن مروان — الخليفة الأموي الذي بنى قبة الصخرة في القدس.", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2385", section: "التاريخ الإسلامي", category: "الدول", level: "صعب", question: "من الخليفة العادل الذي لقّبه العلماء بخامس الخلفاء الراشدين؟", answer: "عمر بن عبد العزيز — الخليفة العادل الذي لقّبه العلماء بخامس الخلفاء الراشدين.", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2386", section: "التاريخ الإسلامي", category: "المعارك", level: "متوسط", question: "ما أول موقعة دارت بين المسلمين أنفسهم في التاريخ الإسلامي؟", answer: "موقعة الجمل — أول موقعة دارت بين المسلمين أنفسهم، وقعت سنة 36هـ.", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2387", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "من الصحابي الذي فتح بيت المقدس في عهد عمر بن الخطاب؟", answer: "حاصرها الجيش الإسلامي بقيادة أبي عبيدة بن الجراح رضي الله عنه، واشترط أهلها أن يتسلّمها أمير المؤمنين بنفسه، فقدم عمر بن الخطاب رضي الله عنه من المدينة وتسلّمها صلحًا وكتب لأهلها العهدة العمرية سنة 15هـ (وقيل 16هـ)", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2388", section: "التاريخ الإسلامي", category: "المعارك", level: "صعب", question: "ما موقعة اليرموك وفيم وقعت؟", answer: "معركة فاصلة بين المسلمين والروم على نهر اليرموك بالشام، أميرُ الجيش فيها أبو عبيدة بن الجراح وللمسلمين فيها تدبير خالد بن الوليد رضي الله عنهما، وبها انكسرت قوة الروم وتمّ فتح الشام. وأشهر ما قيل في تاريخها رجب سنة 15هـ، وقيل سنة 13هـ", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2389", section: "التاريخ الإسلامي", category: "الدول", level: "صعب", question: "ما المدينة التي كانت عاصمة الدولة العثمانية؟", answer: "القسطنطينية (إسطنبول) منذ فتحها سنة 857هـ/1453م إلى نهاية الدولة؛ وقد سبقتها عاصمتان: بورصة ثم أدرنة", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2390", section: "التاريخ الإسلامي", category: "الدول", level: "صعب", question: "في أي سنة أُلغيت الخلافة العثمانية؟", answer: "1342هـ / 1924م، حين أُلغي منصب الخلافة رسمياً في الثالث من مارس 1924م؛ وقد سبق ذلك إلغاء السلطنة العثمانية سنة 1341هـ/1922م", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2391", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "من أسس مدينة الفسطاط في مصر؟", answer: "عمرو بن العاص رضي الله عنه، اختطّها نحو سنة 20هـ/641م بعد فتح حصن بابليون، فكانت أول مدينة أسسها المسلمون في مصر وأول عواصمها الإسلامية. وسُميت بالفسطاط — ومعناه الخيمة أو مجتمع أهل الكورة — لأن مسجد عمرو بُني في موضع فسطاطه، وهو أول مسجد بُني في مصر وإفريقية", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2392", section: "التاريخ الإسلامي", category: "المؤسسات الإسلامية", level: "متوسط", question: "ما أقدم مؤسسة تعليمية إسلامية لا تزال قائمة حتى اليوم؟", answer: "القرويين بمدينة فاس في المغرب؛ أسّستها فاطمة الفهرية سنة 245هـ/859م مسجداً جامعاً، ثم صارت حلقات علم فمؤسسة تعليمية جامعة، وهي مسجَّلة لدى اليونسكو وموسوعة غينيس بوصفها أقدم مؤسسة تعليمية ما زالت تمنح الشهادات. ووصفها بـ«الجامعة» بالمعنى النظامي الحديث متأخر عن نشأتها. ويليها في القدم الجامع الأزهر بالقاهرة (بُني سنة 359هـ/970م)", explanation: "يُستفاد منه في باب المؤسسات الإسلامية. يُستفاد منه في باب المؤسسات الإسلامية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2393", section: "التاريخ الإسلامي", category: "الأيوبيون", level: "سهل", question: "من قاد المسلمين في معركة حطين وفتح بيت المقدس عام 1187م؟", answer: "السلطان صلاح الدين يوسف بن أيوب (532-589هـ)؛ كانت حطين في ربيع الآخر سنة 583هـ/تموز 1187م قرب طبرية، وانكسر بها جيش الصليبيين، فتتابعت له فتوح الساحل حتى استُرِدَّ بيت المقدس في رجب من السنة نفسها/تشرين الأول 1187م، بعد نحو 88 سنة ميلادية (91 سنة هجرية) من احتلاله سنة 492هـ/1099م", explanation: "يُستفاد منه في باب الأيوبيون. يُستفاد منه في باب الأيوبيون مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2394", section: "التاريخ الإسلامي", category: "الدول الإسلامية", level: "متوسط", question: "ما عواصم الدولة الفاطمية؟", answer: "تعاقبت لها عواصم ولم تكن القاهرة أولها: قامت أولاً بإفريقية (تونس اليوم) واتخذت رقّادة ثم بنى مؤسسها مدينة المهدية سنة 308هـ فصارت عاصمتها، ثم المنصورية (صبرة) قرب القيروان، ثم انتقل مركزها إلى مصر بعد أن فتحها القائد جوهر الصقلي سنة 358هـ/969م فبنى مدينة القاهرة، فصارت عاصمة الدولة إلى سقوطها سنة 567هـ/1171م", explanation: "يُستفاد منه في باب الدول الإسلامية. يُستفاد منه في باب الدول الإسلامية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2395", section: "التاريخ الإسلامي", category: "الدول الإسلامية", level: "متوسط", question: "من أسس الدولة الفاطمية؟", answer: "أبو محمد عبيد الله المهدي؛ أُعلنت دولته بإفريقية سنة 297هـ/909م بعد أن مهّد له داعيته أبو عبد الله الشيعي بإسقاط دولة الأغالبة، وتلقّب بـ«المهدي أمير المؤمنين»، وبنى مدينة المهدية. والدولة إسماعيلية المذهب، وقد نازع كثير من المؤرخين وأهل العلم في صحة انتسابهم إلى فاطمة رضي الله عنها، ومن أشهر ما يُذكر في ذلك المحضر الذي كُتب ببغداد سنة 402هـ في إنكار نسبهم", explanation: "يُستفاد منه في باب الدول الإسلامية. يُستفاد منه في باب الدول الإسلامية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2396", section: "التاريخ الإسلامي", category: "الفتوحات", level: "سهل", question: "من فتح بلاد السند فكان فتحه أول باب دخل منه الإسلام إلى شبه القارة الهندية؟", answer: "محمد بن القاسم الثقفي، وجّهه الحجاج بن يوسف والي العراق سنة 92هـ/711م في خلافة الوليد بن عبد الملك، ففتح الدَّيبُل ثم بلاد السند والمُلتان. والذي فتحه هو السند (غربي شبه القارة) لا شبه القارة كلها؛ وإنما امتدّ الإسلام إلى داخلها بعد ذلك بقرون على أيدي الغزنويين (محمود الغزنوي) ثم الغوريين ثم دولة المغول المسلمين في الهند. وقد عُزل محمد بن القاسم بعد موت الحجاج والوليد، وسُجن فمات في خلافة سليمان بن عبد الملك", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2397", section: "التاريخ الإسلامي", category: "المعارك", level: "متوسط", question: "ما اسم المعركة التي حسمت أمر العراق للمسلمين في حربهم مع الفرس؟", answer: "معركة القادسية سنة 15هـ/636م وقيل 14هـ؛ أمير المسلمين فيها سعد بن أبي وقاص رضي الله عنه بتكليف من عمر بن الخطاب رضي الله عنه، وقائد الفرس رستم. وبها استقرّ السواد (العراق) للمسلمين وسقطت المدائن بعدها. وأما المعركة التي أنهت مقاومة الدولة الساسانية في المشرق فهي نهاوند سنة 21هـ، وهي التي سمّاها المؤرخون «فتح الفتوح»", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2398", section: "التاريخ الإسلامي", category: "الخلفاء", level: "متوسط", question: "من أول الخلفاء الراشدين الذي وسّع المسجد النبوي الشريف؟", answer: "عمر بن الخطاب رضي الله عنه، وسّعه سنة 17هـ، ثم وسّعه عثمان بن عفان رضي الله عنه سنة 29هـ فبناه بالحجارة المنقوشة. وينبّه على أن أول زيادة في المسجد كانت من النبي ﷺ نفسه بعد فتح خيبر، فتوسعة عمر رضي الله عنه هي أول توسعة بعده ﷺ", explanation: "يُستفاد منه في باب الخلفاء. يُستفاد منه في باب الخلفاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2399", section: "التاريخ الإسلامي", category: "المعارك", level: "سهل", question: "متى وقعت غزوة بدر الكبرى؟", answer: "في السابع عشر من رمضان سنة اثنتين للهجرة (رمضان 2هـ / مارس 624م) على المشهور عند أهل السير؛ وسمّى الله تعالى يومها «يوم الفرقان» في قوله: ﴿وَمَا أَنْزَلْنَا عَلَى عَبْدِنَا يَوْمَ الْفُرْقَانِ يَوْمَ الْتَقَى الْجَمْعَانِ﴾ [الأنفال: 41]، وقال: ﴿وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنْتُمْ أَذِلَّةٌ﴾ [آل عمران: 123]. وكان المسلمون فيها ثلاث مئة وبضعة عشر رجلًا، ثبت ذلك في البخاري عن البراء بن عازب رضي الله عنه", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2400", section: "التاريخ الإسلامي", category: "الدولة الإسلامية", level: "متوسط", question: "ما أول مدينة اتخذها المسلمون عاصمةً لدولتهم؟", answer: "المدينة المنورة (وكانت تُسمّى يثرب قبل الهجرة)؛ اتخذها النبي ﷺ دار الهجرة ومركز الدولة سنة 1هـ، وبقيت عاصمةً في خلافة أبي بكر وعمر وعثمان رضي الله عنهم، ثم صار مركز الخلافة إلى الكوفة في خلافة علي بن أبي طالب رضي الله عنه سنة 36هـ، ثم إلى دمشق في الدولة الأموية", explanation: "يُستفاد منه في باب الدولة الإسلامية. يُستفاد منه في باب الدولة الإسلامية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2401", section: "التاريخ الإسلامي", category: "الفتوحات", level: "متوسط", question: "من قائد المسلمين في القادسية ومؤسِّس مدينة الكوفة؟", answer: "سعد بن أبي وقاص رضي الله عنه؛ اختطّ الكوفة سنة 17هـ بأمر عمر بن الخطاب رضي الله عنه لتكون منزلًا لجيوش المسلمين. وأما فتح العراق فلم ينفرد به سعد: بدأه خالد بن الوليد رضي الله عنه بفتح الحيرة سنة 12هـ، وتابعه المثنى بن حارثة الشيباني رضي الله عنه، ثم حسمه سعد رضي الله عنه بالقادسية", explanation: "يُستفاد منه في باب الفتوحات. يُستفاد منه في باب الفتوحات مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2402", section: "التاريخ الإسلامي", category: "المعارك", level: "صعب", question: "ما اسم المعركة التي وقفت أمام امتداد الإسلام إلى قلب أوروبا عام 732م؟", answer: "معركة بلاط الشهداء سنة 114هـ/732م، بين تور (Tours) وبواتييه (Poitiers) في بلاد الفرنجة؛ قائد المسلمين عبد الرحمن الغافقي والي الأندلس واستُشهد فيها، وقائد الفرنجة شارل مارتل. ولم تكن نهاية الوجود الإسلامي شمال جبال البرانس: بقيت أربونة (Narbonne) وأقاليم سبتمانيا بأيدي المسلمين بعدها نحو سبع وعشرين سنة (حتى 759م)، وتكررت الحملات، لكنها كانت منتهى التوسّع المنظَّم في داخل بلاد الغال", explanation: "يُستفاد منه في باب المعارك. يُستفاد منه في باب المعارك مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2403", section: "التاريخ الإسلامي", category: "الخلفاء", level: "متوسط", question: "من الخليفة الراشدي الذي استلم مفاتيح بيت المقدس وكتب لأهلها العهدة؟", answer: "عمر بن الخطاب رضي الله عنه؛ حاصر بيت المقدس أبو عبيدة بن الجراح رضي الله عنه، فاشترط أهلها أن يتسلّمها أمير المؤمنين نفسه، فقدم عمر رضي الله عنه من الجابية وكتب لهم العهدة المعروفة بـ«العهدة العمرية» في تأمينهم على أنفسهم وكنائسهم، وذلك سنة 15هـ وقيل 16هـ", explanation: "يُستفاد منه في باب الخلفاء. يُستفاد منه في باب الخلفاء مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2404", section: "التاريخ الإسلامي", category: "الدول الإسلامية", level: "صعب", question: "من كان أول وزير في الدولة العباسية؟", answer: "أبو سلمة حفص بن سليمان الخلّال، وكان يُلقَّب «وزير آل محمد»؛ قام بأمر الوزارة للخليفة أبي العباس السفاح، ثم قُتل سنة 132هـ لِما نُسب إليه من الميل إلى العلويين. وينبّه على أن الوزارة بنظامها المكتمل واستقلال ديوانها إنما تأخّرت إلى عهد البرامكة في خلافة أبي جعفر المنصور ومن بعده", explanation: "يُستفاد منه في باب الدول الإسلامية. يُستفاد منه في باب الدول الإسلامية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2405", section: "التاريخ الإسلامي", category: "السيرة النبوية", level: "متوسط", question: "كم غزوة شارك فيها النبي ﷺ بنفسه؟", answer: "المشهور عند أهل السير والمغازي (كابن إسحاق) سبع وعشرون غزوة، قاتل في تسع منها. وثبت في الصحيحين عن زيد بن أرقم رضي الله عنه أنه غزا ﷺ تسع عشرة غزوة، وجمع العلماء بأن الاختلاف راجع إلى اختلاف المعدود لا إلى تعارض حقيقي: فمن عدّ المنازل والسرايا مستقلةً كثّر العدد، ومن اقتصر على ما اشتُهر منها غزوةً قلّله", explanation: "يُستفاد منه في باب السيرة النبوية. يُستفاد منه في باب السيرة النبوية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2406", section: "التاريخ الإسلامي", category: "الدول الإسلامية", level: "صعب", question: "من الخليفة العباسي الذي قُتل في الفتنة بينه وبين أخيه؟", answer: "الأمين محمد بن هارون الرشيد؛ قُتل سنة 198هـ/813م في حصار بغداد أثناء الفتنة بينه وبين أخيه المأمون، فصارت الخلافة إلى المأمون. ولم يقتله المأمون بيده ولا كان حاضرًا — كان بخُراسان — وإنما قتله رجال جيشه الذي قاده طاهر بن الحسين، فالخلط بين الآمر والمنفِّذ خطأ شائع في هذه الواقعة", explanation: "يُستفاد منه في باب الدول الإسلامية. يُستفاد منه في باب الدول الإسلامية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2407", section: "التاريخ الإسلامي", category: "الدول الإسلامية", level: "متوسط", question: "ما أكبر الإمبراطوريات الإسلامية مساحةً في التاريخ؟", answer: "الدولة الأموية؛ وبلغت أقصى اتساعها في عهد الوليد بن عبد الملك (86-96هـ) الذي تمّ فيه فتح الأندلس وبلاد السند وما وراء النهر، فامتدّت من الأندلس والمغرب غربًا إلى تخوم الصين وحدود الهند شرقًا — أي إلى أطراف الصين لا إلى الصين نفسها. وتقديرات مساحتها عند المؤرخين المعاصرين متفاوتة، وهي تُعدّ من أوسع الدول في التاريخ مساحةً", explanation: "يُستفاد منه في باب الدول الإسلامية. يُستفاد منه في باب الدول الإسلامية مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2408", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "من أسّس الدولة الأموية؟", answer: "معاوية بن أبي سفيان رضي الله عنه سنة 41هـ، حين تنازل له الحسن بن علي رضي الله عنهما فاجتمعت عليه الأمة، وسُمّي ذلك العام «عام الجماعة»", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2409", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "من أسّس الدولة العباسية؟", answer: "أبو العبّاس عبد الله بن محمد بن علي بن عبد الله بن العبّاس، الملقّب بالسفّاح — بويع بالخلافة في الكوفة سنة 132هـ بسقوط الدولة الأموية", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2410", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "متى أُلغيت الخلافة العثمانية؟", answer: "أُلغيت رسميًّا في الثالث من مارس سنة 1924م (1342هـ) بقرار الجمعية الوطنية التركية برئاسة مصطفى كمال (ولم يُلقَّب بـ«أتاتورك» إلا سنة 1934م)؛ وقد سبق ذلك إلغاء السلطنة سنة 1341هـ/1922م، وآخر من حمل لقب الخليفة عبد المجيد الثاني. والأدقّ أنها أُلغيت بقرارٍ داخليّ لا أنها «سقطت» بغزو", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2411", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "من أسّس السلطنة العثمانية؟", answer: "عثمان الأول بن أرطغرل سنة 699هـ/1299م، وكانت في أوّلها إمارةً حدوديّةً صغيرة في شمال غرب الأناضول (سُكود/سوغوت) بعد تفكّك دولة سلاجقة الروم؛ ولم تُوصف بـ«الخلافة» إلا بعد فتح سليم الأول لمصر سنة 923هـ/1517م وزوال الخلافة العباسية الاسمية بالقاهرة — فالتسمية بالسلطنة أدقّ في أوّل عهدها", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2412", section: "التاريخ الإسلامي", category: "الدول", level: "صعب", question: "ما أطول دولة إسلامية حكمت في التاريخ؟", answer: "الدولة العثمانية؛ امتدّت 643 سنة هجرية (699-1342هـ) وهي نحو 625 سنة ميلادية (1299-1924م) — والتنبّه للفرق بين التقويمين لازم، فالسنة الهجرية أقصر — وتُعدّ أطول دولة إسلامية بسلطة سياسية فعلية متصلة. تليها الخلافة العباسية ببغداد: 524 سنة هجرية (132-656هـ) وهي نحو 508 سنوات ميلادية (750-1258م)، وما بقي منها بالقاهرة بعد ذلك (659-923هـ) كان خلافةً اسميّةً تحت المماليك بلا سلطة فعلية", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2413", section: "التاريخ الإسلامي", category: "الدول", level: "متوسط", question: "ما الدولة الإسلامية التي حكمت الأندلس لأطول مدة؟", answer: "دولة بني أمية في الأندلس؛ أسّسها عبد الرحمن الداخل إمارةً سنة 138هـ/756م، وأعلنها عبد الرحمن الناصر خلافةً سنة 316هـ/929م، وانتهت سنة 422هـ/1031م فقام عصر ملوك الطوائف — فمدّتها 284 سنة هجرية (نحو 275 ميلادية)، تليها دولة بني نصر (بني الأحمر) بغرناطة نحو 262 سنة هجرية (635-897هـ)", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" },
  { id: "2414", section: "التاريخ الإسلامي", category: "الدول", level: "صعب", question: "في أي سنة سقطت بغداد على يد المغول؟", answer: "سنة 656هـ/1258م على يد هولاكو حفيد جنكيز خان؛ وقُتل فيها المستعصم بالله آخر خلفاء بني العباس ببغداد فانتهت الخلافة العباسية في العراق، ثم أُقيمت خلافة عباسية اسمية بالقاهرة في ظلّ المماليك سنة 659هـ. وأوقف زحفَ المغول انتصارُ المماليك في عين جالوت سنة 658هـ/1260م", explanation: "يُستفاد منه في باب الدول. يُستفاد منه في باب الدول مع الرجوع إلى مراجع سُنّة.", reference: "مراجع سُنّة" }
];

