export const FAWAID_ITEMS = [
  { text: "الحكمة في الدعوة لا تعني التنازل عن الحق؛ بل حسن اختيار الوقت والأسلوب، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما دلّ عليه الكتاب والسنة.", category: "الدعوة", source: "تفسير ابن سعدي — النحل: 125", author_name: "ابن سعدي" },
  { text: "الزهد في الدنيا ليس ترك أسبابها؛ بل ألا تستعبدك ولا تملأ قلبك، وهذا من تزكية النفس التي يُقرب بها العبد من ربه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الرقائق", source: "مدارج السالكين — ابن القيم", author_name: "ابن قيم الجوزية" },
  { text: "ما أُفرغ في جوف ابن آدم أشد من الحب والغضب؛ فداوِهما بالصبر والاستعاذة، وهذا من تزكية النفس التي يُقرب بها العبد من ربه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الرقائق", source: "إغاثة اللهفان — ابن القيم", author_name: "ابن قيم الجوزية" },
  { text: "أكبر الكبائر: الإشراك بالله، والأمن من مكر الله، والقنوط من رحمة الله، واليأس من روح الله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..", category: "الرقائق", source: "أثر عن عبدالله بن مسعود — رواه عبدالرزاق والطبراني في الكبير وذكره ابن جرير، إسناده صحيح", author_name: "عبدالله بن مسعود" },
  { text: "قيمة المرء بأخلاقه لا بماله ولا بجاهه — معنى أدبي يُنسب لشعر الشافعي؛ يُذكر أدباً لا حديثاً. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "يُنسب لديوان الشافعي — أدب لا مرفوع", author_name: "يُنسب للإمام الشافعي" },
  { text: "من جمع بين حسن الخُلق والعلم فقد أوتي خير الدنيا والآخرة، وهذا من مكارم الأخلاق التي أمر بها الشرع. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "أدب الدنيا والدين — الماوردي", author_name: "الماوردي" },
  { text: "الكرم في النفس أعلى درجات الكرم؛ أن تجود بنفسك على الحق وإن شق، وهذا من مكارم الأخلاق التي أمر بها الشرع. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "مدارج السالكين — ابن القيم", author_name: "ابن قيم الجوزية" },
  { text: "التفسير بالرأي المجرد دون علم محرّم؛ وتفسير القرآن بالقرآن هو أعلى درجات البيان، وهذا بيان يُعين على فهم مراد الله في كتابه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "مقدمة في أصول التفسير — ابن تيمية", author_name: "ابن تيمية" },
  { text: "القرآن تدبّره في السر ثمرته في العلانية؛ من تدبّر آياته ظهر ذلك في سلوكه، وهذا بيان يُعين على فهم مراد الله في كتابه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "التبيان في آداب حملة القرآن — النووي", author_name: "الإمام النووي" },
  { text: "الأصل في الأشياء الإباحة حتى يرد دليل على التحريم — قاعدة ذهبية في الفقه الإسلامي، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "قواعد الأحكام — العز بن عبد السلام", author_name: "العز بن عبد السلام" },
  { text: "درء المفسدة مقدّم على جلب المصلحة؛ وهذا أصل عظيم في الاجتهاد الفقهي، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "الأشباه والنظائر — ابن نجيم", author_name: "ابن نجيم الحنفي" },
  { text: "خيركم خيركم لأهله — الأسرة الصالحة أساس المجتمع المسلم الصالح، وهذا من أصول التربية الإسلامية التي يُنشأ عليها الولد. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "الترمذي ٣٨٩٥ — صححه الألباني", author_name: "النبي محمد ﷺ" },
  { text: "تعليم الصلاة مقدَّم في تربية الأولاد؛ قال ﷺ: «مروا أولادكم بالصلاة لسبع» — أبو داود حسّنه الألباني. وأما صياغة «البيت السعيد…» فتعبير تربوي حديث لا مرفوع.", category: "التربية", source: "أبو داود ٤٩٥؛ صياغة البيت من كتب التربية المعاصرة (علوان) لا حديث", author_name: "صحيح البخاري" },
  { text: "التوحيد أسُّ الدين وقمّته؛ فلا عمل يُقبل بلا توحيد، ولا توحيد يكتمل بلا إخلاص، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "درء تعارض العقل والنقل — ابن تيمية", author_name: "ابن تيمية" },
  { text: "اليقين هو الركن الركين في بنيان الإيمان؛ من رُزق اليقين هانت عليه الدنيا وعظمت عنده الآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "مدارج السالكين — ابن القيم", author_name: "ابن قيم الجوزية" },
  { text: "الإيمان قول وعمل ونية — لا يصح بعضها دون بعض في منظومة الاعتقاد الصحيح، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "شرح السنة — الإمام البغوي", author_name: "الإمام البغوي" },
  { text: "لا تصلح الأُمة حتى يصلح علماؤها؛ وعلماء الأمة مصابيح الهداية في الظلمات، وهذا من آداب طلب العلم وأصوله التي يُرجى بها نفع العلم. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "جامع بيان العلم — ابن عبد البر", author_name: "ابن عبد البر" },
  { text: "من أدب طالب العلم أن لا يفتتن بمدح الناس ولا ينكسر بذمهم في طلبه — معنى مبثوث في كتب آداب الطلب كالجامع للخطيب؛ ليس حديثاً مرفوعاً. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "معنى من آداب الطلب (الجامع لأخلاق الراوي ونحوه) — أدب لا مرفوع", author_name: "الخطيب البغدادي (معنى)" },
  { text: "من أراد علم الأولين والآخرين فليتدبّر القرآن — فيه جواب كل سؤال وشفاء كل داء، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. كما ثبت في السنة الصحيحة.", category: "القرآن", source: "أثر عن عبدالله بن مسعود — رواه أحمد في الزهد وابن أبي شيبة والطبراني في الكبير والبيهقي في شعب الإيمان، نقله ابن تيمية في مقدمة في أصول التفسير", author_name: "عبدالله بن مسعود" },
  { text: "الحافظ للقرآن يُقال له يوم القيامة: اقرأ وارتقِ ورتّل — فمنزلته عند آخر آية يقرؤها، فالتعامل مع كتاب الله يستوجب تدبره وحفظه والعمل بما فيه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "القرآن", source: "الترمذي ٢٩١٤ وأبو داود ١٤٦٤ — حسّنه الألباني", author_name: "النبي محمد ﷺ" },
  { text: "القدوة أبلغ من الوعظ؛ والأصل: ﴿أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ﴾. صياغة «التربية تبدأ بالنفس…» تعبير معاصر لا مرفوع. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "البقرة: ٤٤؛ صياغة معاصرة في كتب التربية (علوان ونحوه)", author_name: "صحيح البخاري" },
  { text: "لا تُكثر أمر ولدك بالنهي؛ فإن الإكثار يُفضي إلى الجرأة. علّمه بالترغيب قبل الترهيب، وهذا من أصول التربية الإسلامية التي يُنشأ عليها الولد. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "أدب الدنيا والدين — الماوردي", author_name: "الماوردي" },
  { text: "صحيح البخاري أصح الكتب بعد كتاب الله؛ وقد استغرق البخاري ستة عشر عاماً في تصنيفه، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "هدي الساري مقدمة فتح الباري — ابن حجر العسقلاني", author_name: "ابن حجر العسقلاني" },
  { text: "ما صحّ عن النبي ﷺ حجة بنفسه عند أهل السنة؛ والعمل به لا يتوقف على موافقة مذهب معيّن — تقرير أصولي معروف عند المحدّثين والفقهاء المحققين. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "تقرير أصولي عند أهل السنة (انظر كلام الألباني في صفة الصلاة ونحوه)", author_name: "أصول أهل السنة" },
  { text: "الفقه ليس حفظ المسائل فحسب؛ بل فهم المقاصد وتنزيلها على الوقائع. والفقيه من يُحسن ذلك، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "الموافقات — أبو إسحاق الشاطبي", author_name: "الشاطبي" }
];
